&lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;span style="color:#0000CD"&gt;&lt;strong&gt;WHAT:&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;span style="color:rgb(36, 36, 36); font-family:arial,arial_embeddedfont,arial_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
